                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: new URLSearchParams({
                    'csrf_token': '<CSRF_TOKEN:value>',
                    'some_field': '<SOME_FIELD:value>'
                })
